// Generated by Cypress Author on 2026-10-30.
import { callAs, callRefused, randomId, readRecord, refAs } from "../../../../support/odoo";
import { openTab, pick, save } from "../../../../support/form";

const ADMINISTRATOR = "demo.administrator";
const SALES = "demo.sales";
const CHLORPYRIFOS = "sol_demo.demo_test_parameter_chlorpyrifos";

// A new narrower type of Vegetables, so each run configures a sample type nothing else uses.
function newVegetable(name) {
  return refAs(ADMINISTRATOR, "sol_demo.demo_sample_type_vegetables").then(({ id }) =>
    callAs(ADMINISTRATOR, "medilab.sample.type", "create", [{ name, parent_id: id }]),
  );
}

// A claimed quotation of sales for Chlorpyrifos, with no sample yet.
function chlorpyrifosQuotation() {
  return refAs(SALES, CHLORPYRIFOS)
    .then(({ id }) => callAs(SALES, "product.product", "search", [[["parameter_id", "=", id]]], { limit: 1 }))
    .then(([productId]) =>
      refAs(SALES, "sol_demo.demo_res_partner_nuoc_sach").then(({ id: customerId }) =>
        refAs(SALES, "sol_demo.demo_res_partner_hoa").then(({ id: contactId }) =>
          callAs(SALES, "sale.order", "create", [
            {
              customer_id: customerId,
              partner_id: contactId,
              source: "portal",
              order_status: "submitted",
              order_line: [[0, 0, { product_id: productId, product_uom_qty: 1 }]],
            },
          ]),
        ),
      ),
    )
    .then((orderId) => callAs(SALES, "sale.order", "action_claim", [[orderId]]).then(() => orderId));
}

function addSample(orderId, sampleTypeId, name) {
  return callAs(SALES, "medilab.order.sample", "create", [
    { order_id: orderId, customer_sample_name: name, sample_type_id: sampleTypeId, physical_state: "solid" },
  ]);
}

describe("Ways of testing per sample type", () => {
  it("TC-F409: configuring a sample type on a parameter → it is offered there and nowhere else", () => {
    const kale = `Kale ${randomId().slice(0, 8)}`;
    newVegetable(kale).as("kale");

    // The administrator makes the in-house QuEChERS way apply to the new type, with an LOQ and no LOD.
    cy.signInAs("administrator");
    cy.openRecord(CHLORPYRIFOS);
    openTab("sample_types");
    cy.get(".o_field_widget[name=applicability_ids] .o_field_x2many_list_row_add button").click();
    pick("sample_type_id", kale);
    pick("parameter_method_id", "EN 15662:2018");
    pick("unit_id", "mg/kg");
    cy.get(".o_field_widget[name=loq] input").clear().type("0.01");
    cy.get(".o_field_widget[name=is_default] input").check();
    save();

    cy.get("@kale").then((kaleId) => {
      readRecord(CHLORPYRIFOS, ["sample_type_ids"]).then(({ sample_type_ids }) => {
        expect(sample_type_ids, "sample types the parameter is offered on").to.include(kaleId);
      });
      callAs(ADMINISTRATOR, "medilab.parameter.method.sample.type", "search_read", [[["sample_type_id", "=", kaleId]]], {
        fields: ["lod", "loq", "is_default"],
      }).then(([applicability]) => {
        // An LOD left empty stays empty instead of becoming zero.
        expect(applicability).to.include({ lod: false, loq: 0.01, is_default: true });
      });

      // Sales tests the quotation on a Kale sample; Lettuce, a sibling with nothing configured, is refused.
      chlorpyrifosQuotation().then((orderId) => {
        callAs(SALES, "sale.order", "read", [[orderId], ["order_line"]]).then(([{ order_line: lines }]) => {
          addSample(orderId, kaleId, kale).then((kaleSampleId) => {
            callAs(SALES, "sale.order.line", "write", [lines, { sample_id: kaleSampleId }]);
            callAs(SALES, "sale.order.line", "read", [lines, ["sample_id"]]).then(([line]) => {
              expect(line.sample_id[0], "sample the line is tested on").to.equal(kaleSampleId);
            });
          });
          refAs(SALES, "sol_demo.demo_sample_type_lettuce").then(({ id: lettuceId }) =>
            addSample(orderId, lettuceId, "Lettuce").then((lettuceSampleId) => {
              cy.signInAs("sales");
              callRefused("sale.order.line", "write", [lines, { sample_id: lettuceSampleId }]).then((message) => {
                // The message is in the salesperson's language; it names the parameter and the sample type.
                expect(message).to.contain("Chlorpyrifos").and.to.contain("Lettuce");
              });
            }),
          );
        });
      });
    });
  });
});
